{
  "Q1": {
    "q1_duty_procs": {
      "verdict": "yes",
      "rationale": "Table lists 11046 (2026-14991), 11047 (2026-14992), 11048 (2026-14997), all 'Signed; published' July 20 / July 23, 2026."
    },
    "q1_details": {
      "verdict": "yes",
      "rationale": "All ten documents carry the key's first pages (46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) with accurate one-line descriptions (50% duties; delay; exclusions; Part A/B scope modifications incl. 11076's reversal)."
    },
    "q1_delay": {
      "verdict": "yes",
      "rationale": "11056 / 2026-17294, signed Aug. 18, published Aug. 24, 'Changes the three duty effective dates to 12:01 a.m. Aug. 22' from the printed Aug. 19."
    },
    "q1_exclusions": {
      "verdict": "yes",
      "rationale": "11061/11062/11063 with 2026-18835/-18836/-18837, Sept. 8 / Sept. 14, and operative time 'imported from 12:01 a.m. Sept. 29'."
    },
    "q1_scope": {
      "verdict": "yes",
      "rationale": "11064 and 11065 (2026-18838, 2026-18839), Sept. 8, applying 'from 12:01 a.m. Sept. 15'; 11076 (2026-22292), Oct. 23 / Oct. 30, applying 'from 12:01 a.m. Oct. 30'."
    },
    "q1_events": {
      "verdict": "yes",
      "rationale": "Duties and scope changes described as measured by 'consumption entry or warehouse withdrawal'; exclusions repeatedly described as measured by importation ('the event is importation, not consumption entry')."
    },
    "q1_dairy_none": {
      "verdict": "yes",
      "rationale": "Product-scope paragraph assigns alcohol to 11046/11064/11061 and motor vehicles to 11048/11065/11076/11063, and for dairy says only 'first listed by 11047 and partially excluded by 11062' — no dairy scope modification is attributed to any document."
    },
    "q1_dairy_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty field: 'Proclamation 11062, clause (3), refers to a September 8 dairy scope proclamation. No such proclamation was found in the Federal Register series through November 14.'"
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Every row and claim carries a document number and FR page or clause citation (e.g. '2026-18835; 91 FR 58311'); citation discipline is met."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "All document numbers, pages and proclamation numbers match the published record; no invented source or quotation."
    }
  },
  "Q2": {
    "q2a_zero": {
      "verdict": "yes",
      "rationale": "Entries 1 and 2: '$40,000 × 0% = $0' each."
    },
    "q2a_third": {
      "verdict": "yes",
      "rationale": "Entry 3: '$40,000 × 50% = $20,000', noting the change at 12:01 a.m. Aug. 22."
    },
    "q2a_basis": {
      "verdict": "yes",
      "rationale": "Basis cites 'FR Doc. 2026-17294 ... clauses (1), (4)–(5), 91 FR 54790–91' and describes clause (1) as setting 12:01 a.m. Aug. 22."
    },
    "q2b_chapeau": {
      "verdict": "yes",
      "rationale": "'substitutes that date in the chapeau of Annex II of each original proclamation. It does not literally amend the August 19 text in clauses (1) and (3) or the recital'."
    },
    "q2b_resolve": {
      "verdict": "yes",
      "rationale": "'Its later operative date and clause (5)'s supersession of inconsistent prior provisions resolve the difference.'"
    },
    "q2c_refund": {
      "verdict": "yes",
      "rationale": "Cites 11056 clause (4): refunds 'processed under applicable law and CBP's standard procedures', and notes no deadline is specified."
    },
    "q2d_no_action": {
      "verdict": "yes",
      "rationale": "'No further presidential action was needed: the suspension expired by its own terms'; later recitals say the suspension lapsed and duties became effective at 12:01 a.m. Aug. 22."
    },
    "q2d_reneged": {
      "verdict": "yes",
      "rationale": "'Later recitals say Canada reneged and ceased negotiating in good faith on August 21', citing 2026-18835 recitals 2–4 at 91 FR 58311."
    },
    "q2e_thirty": {
      "verdict": "yes",
      "rationale": "'The original finding was signed July 20. July 20 + 30 days = August 19', tied to the recital that section 338 duties may not take effect earlier than 30 days after the proclamation."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "Citations are given for each part (2026-14991 recital 10 and clauses (1),(3); 2026-17294 clauses (1),(4)-(5); 2026-18835 recitals)."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented document, page, clause or quotation; the quoted/paraphrased content matches the proclamations."
    }
  },
  "Q3": {
    "q3a_shipment_a": {
      "verdict": "yes",
      "rationale": "A: permitted; '$30,000 × 50% = $15,000'."
    },
    "q3a_shipment_b": {
      "verdict": "yes",
      "rationale": "B: 'the September 27 importation precedes the ban; the October 5 warehouse withdrawal remains subject to ... $15,000'."
    },
    "q3a_shipment_c": {
      "verdict": "yes",
      "rationale": "C: 'importation at 11:30 p.m. September 28 precedes the ban; the later entry remains subject to ... $15,000'."
    },
    "q3a_shipment_d": {
      "verdict": "yes",
      "rationale": "D: 'importation at 12:30 a.m. September 29 is excluded'."
    },
    "q3b_result": {
      "verdict": "yes",
      "rationale": "E: 'most defensible reading is that it is not barred ... and remains subject to ... $15,000' on entry from the zone."
    },
    "q3b_ftz": {
      "verdict": "yes",
      "rationale": "Cites the FTZ clause: 'a duty-subject article had to be admitted in privileged foreign status unless eligible for domestic status' (11046 clause (4), 91 FR 46641), and the uncertainty notes the exclusion is silent on zones."
    },
    "q3c_invalid": {
      "verdict": "yes",
      "rationale": "'Proclamation 11061, clause (9)(b), makes the 50% duty apply to the import to which the invalidated ban applied: ... $15,000'."
    },
    "q3d_no_change": {
      "verdict": "yes",
      "rationale": "Answers 'No' — the exclusion 'leaves the other duty-covered products' as they were; basis cites 11061 clauses (1)–(3)."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "Basis gives 2026-18835 clauses (1)–(3), (9)(b) at 91 FR 58312–13 and 2026-14991 clause (4) at 46641."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No invented sources; provisions cited exist and are accurately characterised."
    }
  },
  "Q4": {
    "q4a_amounts": {
      "verdict": "yes",
      "rationale": "'September 10, for each X, Y and Z: section 232 is ... $25,000; section 338 is ... $0'."
    },
    "q4a_basis": {
      "verdict": "yes",
      "rationale": "'Each original proclamation excludes articles subject to section 232 duties', cited to clause (2) of 11046/11047/11048 at 46641, 46655, 46665."
    },
    "q4b_x": {
      "verdict": "yes",
      "rationale": "X: 232 $25,000; 338 $50,000, under 11064 clause (1), 91 FR 58332."
    },
    "q4b_z": {
      "verdict": "yes",
      "rationale": "Z: 232 $25,000; 338 $50,000, under 11065 clause (1), 91 FR 58340."
    },
    "q4b_y": {
      "verdict": "yes",
      "rationale": "Y: 232 $25,000; 338 $0, because 'No corresponding dairy modification was found'; the uncertainty field flags the missing dairy scope proclamation. It chooses $0 as the published-text answer."
    },
    "q4c_text": {
      "verdict": "yes",
      "rationale": "Quotes clause (2) ('shall not apply to articles subject to duties pursuant to section 232') and the later 'as modified in this proclamation, shall apply in addition to duties imposed pursuant to section 232', with the Sept. 15 effective date; pages given."
    },
    "q4c_supersede": {
      "verdict": "yes",
      "rationale": "Presents the later stacking clause as controlling ('as modified in this proclamation') and applies it only from Sept. 15; the criterion expressly allows an answer that cites both clauses with pages and applies the later one from Sept. 15."
    },
    "q4c_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty: 'The dairy exclusion proclamation refers to a dairy scope proclamation that was not found', and Q1 (same question series) identifies it as 11062 clause (3), Sept. 8."
    },
    "q4c_doubt": {
      "verdict": "yes",
      "rationale": "The uncertainty qualifies Y: the result rests on the absence of a dairy scope modification document ('The answer uses the operative documents actually published through today')."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "Each result is tied to a document, clause and FR page."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented sources or quotations; all cited text exists."
    }
  },
  "Q5": {
    "q5a_p": {
      "verdict": "yes",
      "rationale": "P: 'No; yes; yes; yes; yes' — matches the key for all five times."
    },
    "q5a_q": {
      "verdict": "yes",
      "rationale": "Q: 'Yes; no; no; no; no' — matches."
    },
    "q5a_r": {
      "verdict": "yes",
      "rationale": "R: 'Yes; yes; yes; no; no' — October Part A removes it from Oct. 30; matches."
    },
    "q5a_s": {
      "verdict": "yes",
      "rationale": "S: 'No; no; no; yes; yes' — October Part B adds it from Oct. 30; matches."
    },
    "q5b_dates": {
      "verdict": "yes",
      "rationale": "'signed October 23, filed October 29 at 11:15 a.m., and published October 30, 2026. It applies from 12:01 a.m. October 30' — all four elements."
    },
    "q5b_prospective": {
      "verdict": "yes",
      "rationale": "'The September and October scope changes are prospective by those terms; neither provides a refund for earlier entries.'"
    },
    "q5c_days": {
      "verdict": "yes",
      "rationale": "'P and S each became dutiable seven calendar days after the relevant scope proclamation was signed.'"
    },
    "q5c_silent": {
      "verdict": "yes",
      "rationale": "'Each scope proclamation repeats the 30-day description of section 338 but does not explain its application to newly added products', with the uncertainty field saying the point is unresolved."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "Basis cites 2026-18839 recital 8 and clauses (1)–(2) at 91 FR 58340, 2026-22292 at 68862 and the filing line at 68871."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented sources; the filing time and page match the published document."
    }
  },
  "Q6": {
    "q6a_switzerland": {"verdict": "yes", "rationale": "$100,000 × 8.5% = $8,500; total $12,500."},
    "q6a_norway": {"verdict": "yes", "rationale": "$100,000 × 12.5% = $12,500; total $16,500."},
    "q6a_uk": {"verdict": "yes", "rationale": "$100,000 × 10% = $10,000; total $14,000."},
    "q6a_germany": {"verdict": "yes", "rationale": "$100,000 × 6% = $6,000; total $10,000."},
    "q6a_taiwan": {"verdict": "yes", "rationale": "$100,000 × 6% = $6,000; total $10,000."},
    "q6a_turkiye": {"verdict": "yes", "rationale": "$100,000 × 12.5% = $12,500; total $16,500."},
    "q6a_japan": {"verdict": "yes", "rationale": "$100,000 × 8.5% = $8,500; total $12,500."},
    "q6a_liechtenstein": {"verdict": "yes", "rationale": "$0 (not one of the 60 investigated economies); total $4,000, and the text notes Liechtenstein was not investigated."},
    "q6a_hongkong": {"verdict": "yes", "rationale": "$100,000 × 12.5% = $12,500; total $16,500."},
    "q6a_india": {"verdict": "yes", "rationale": "$100,000 × 10% = $10,000; total $14,000."},
    "q6b_germany12": {"verdict": "yes", "rationale": "Germany, MFN 12%: $0 (MFN ≥ 10%)."},
    "q6b_japan12": {"verdict": "yes", "rationale": "Japan, MFN 12%: '12.5% − 12%' = $500."},
    "q6b_taiwan10": {"verdict": "yes", "rationale": "Taiwan, MFN exactly 10%: $0."},
    "q6b_korea10": {"verdict": "yes", "rationale": "South Korea, MFN exactly 10%: $2,500."},
    "q6b_swiss_free": {"verdict": "yes", "rationale": "Switzerland duty-free: $100,000 × 12.5% = $12,500."},
    "q6c_net": {
      "verdict": "yes",
      "rationale": "'flat additional 10% for the EU and Taiwan; the adopted treatment nets MFN against 10% ... flat additional 12.5% for Japan and Switzerland; adopted nets MFN against 12.5%' — all four named, and no claim that Norway/UK/Türkiye/Hong Kong changed."
    },
    "q6c_india": {
      "verdict": "yes",
      "rationale": "'India changed from a proposed flat 12.5% to flat 10% after adopting an import prohibition', with the memorandum and notice cited."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "Rates tied to 2026-11296 at 91 FR 34274, 2026-15274 at 47717–18/47720, and 2026-15181 at 47318–21."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "The 'stated reason for netting' is genuine: memorandum at 91 FR 47719–47720 ('consistent with their respective Agreements on Reciprocal Trade or similar arrangements ... appropriate to encourage these economies'), verified by grep."
    }
  },
  "Q7": {
    "q7a_france": {"verdict": "yes", "rationale": "$60 duty, 0.5% equivalent, 10% − 0.5% = 9.5%, $1,140."},
    "q7b_italy": {"verdict": "yes", "rationale": "$1,800 total duty, 9% equivalent, 1% → $200."},
    "q7b_japan": {"verdict": "yes", "rationale": "12.5% − 9% = 3.5% → $700."},
    "q7b_brazil": {"verdict": "yes", "rationale": "Flat 12.5% → $2,500, no conversion or cap."},
    "q7c_taiwan": {"verdict": "yes", "rationale": "11% ≥ 10% cap → $0."},
    "q7c_switzerland": {"verdict": "yes", "rationale": "12.5% − 11% = 1.5% → $300."},
    "q7d_note": {"verdict": "yes", "rationale": "Identifies 'chapter 99 U.S. note 52(k)' at 91 FR 47394 as the division rule."},
    "q7d_zero": {"verdict": "yes", "rationale": "Locates the zero rule in 'section 1(a)(ii) of the presidential memorandum and in the notice's economy determinations' (91 FR 47720, 47320–28); does not attribute it to 52(k)."},
    "q7_cite": {"verdict": "no", "rationale": "Citations to note 52(k) and memorandum sec. 1(a)(ii) given with pages."},
    "q7_fab": {"verdict": "no", "rationale": "No invented source; the note and memorandum provisions exist as described."}
  },
  "Q8": {
    "q8a_case1": {"verdict": "yes", "rationale": "Case 1: $10,000, 'entry is not before July 28'."},
    "q8a_case2": {"verdict": "yes", "rationale": "Case 2: $0, qualifying vessel transit and entry before July 28."},
    "q8a_case3": {"verdict": "yes", "rationale": "Case 3: $10,000, 'the exception ended at 12:01 a.m. July 28'."},
    "q8a_case4": {"verdict": "yes", "rationale": "Case 4: $10,000, 'loading was after the July 24 cutoff'."},
    "q8a_case5": {"verdict": "yes", "rationale": "Case 5: $0, 'entry preceded the effective time'."},
    "q8a_case6": {"verdict": "yes", "rationale": "Case 6: $10,000, warehouse withdrawal after the start with no qualifying transit."},
    "q8a_case7": {"verdict": "yes", "rationale": "Case 7: $10,000, 'aircraft loading does not meet the DATES line's vessel requirement'."},
    "q8b_where": {"verdict": "yes", "rationale": "'The transit exception is in the DATES line of FR Doc. 2026-15181, 91 FR 47318', with both conditions stated."},
    "q8c_dates": {"verdict": "yes", "rationale": "Signed July 23; duties from 12:01 a.m. Eastern July 24; notice published July 28."},
    "q8d_july30": {"verdict": "yes", "rationale": "July 30: $10,000; the 9903.04.60–9903.04.66 exemption 'begins July 31'."},
    "q8d_aug3": {"verdict": "yes", "rationale": "August 3: $0 under the July 31 exemption."},
    "q8_cite": {"verdict": "no", "rationale": "Basis cites DATES and the Dominican Republic determination at 47318/47323 and Annex I Part B at 47394."},
    "q8_fab": {"verdict": "no", "rationale": "No invented source or quotation."}
  },
  "Q9": {
    "q9a_assembly": {"verdict": "yes", "rationale": "($100,000 − $35,000) × 12.5% = $8,125."},
    "q9b_repairs": {"verdict": "yes", "rationale": "$6,000 × 12.5% = $750, with the full value expressly not the base."},
    "q9c_usmca": {"verdict": "yes", "rationale": "(i) USMCA free entry: $0."},
    "q9c_no_claim": {"verdict": "yes", "rationale": "(ii) $50,000 × 10% = $5,000."},
    "q9d_car": {"verdict": "yes", "rationale": "Car under 9903.94.01: $0."},
    "q9e_reading": {
      "verdict": "yes",
      "rationale": "Concludes '$100,000 × 12.5% = $12,500, assuming no other applicable exemption. A section 232 duty under an unmentioned heading is not by itself the categorical exemption described in the adopted note.' It does not treat the product as exempt."
    },
    "q9e_flag": {
      "verdict": "yes",
      "rationale": "The (e) answer caveats that an unlisted section 232 heading is not covered by the adopted note (i.e. note 52(f) does not address headings it does not list), and (f) contrasts the proposal's general section 232 exclusion with the adopted particular-heading list. The caveat attaches to (e) and points to the note's silence on unlisted headings."
    },
    "q9f_232": {
      "verdict": "yes",
      "rationale": "'The June proposal described an exclusion for all articles and parts subject to section 232 tariffs ... The adopted note instead specifies particular section 232 categories and headings.'"
    },
    "q9f_info": {
      "verdict": "yes",
      "rationale": "'The June proposal described an exclusion for ... informational materials and donations. The adopted note ... does not provide a readable blanket exclusion for ... informational materials, or donations.'"
    },
    "q9_cite": {"verdict": "no", "rationale": "Notes 52(a), (f)(2), (h) and the proposal are cited with pages (47352, 47362–63; 34274, 34276)."},
    "q9_fab": {"verdict": "no", "rationale": "No invented sources; the note provisions cited exist and are accurately characterised."}
  },
  "Q10": {
    "q10a_338": {"verdict": "yes", "rationale": "September 10: section 338 '$0 because the original motor-vehicles duty excludes section 232 articles'."},
    "q10a_301": {"verdict": "yes", "rationale": "Section 301 $0 under note 52(f)(1)."},
    "q10a_total": {"verdict": "yes", "rationale": "MFN $6,000 + 232 $100,000 = $106,000."},
    "q10b_338": {"verdict": "yes", "rationale": "September 16: section 338 $100,000 after the stacking change."},
    "q10b_total": {"verdict": "yes", "rationale": "$6,000 + $100,000 + $100,000 + $0 = $206,000."},
    "q10c_338": {"verdict": "yes", "rationale": "USMCA whisky entry: section 338 '$60,000 × 50% = $30,000'; no USMCA carve-out asserted."},
    "q10c_301": {"verdict": "yes", "rationale": "Section 301 $0 under note 52(g); total $30,000."},
    "q10d_stack": {"verdict": "yes", "rationale": "Section 338 $30,000 + section 301 '$60,000 × 10% = $6,000' = $36,000."},
    "q10e_excluded": {"verdict": "yes", "rationale": "'Arrival October 2 is after the September 29 import exclusion. The shipment is barred.'"},
    "q10f_ieepa": {"verdict": "yes", "rationale": "'Executive Order 14389 ended the IEEPA tariff actions in February 2026', with FR Doc. 2026-03832, 91 FR 9437 cited in the basis."},
    "q10f_surcharge": {"verdict": "yes", "rationale": "Surcharge 'ran from February 24 through the July 24, 2026 endpoint stated in Proclamation 11012', citing 2026-03824 clause (7), 91 FR 9343."},
    "q10_cite": {"verdict": "no", "rationale": "Every layer and document is cited with page numbers."},
    "q10_fab": {"verdict": "no", "rationale": "The extra source cited (2026-20228, 91 FR 63300) exists and does report that the Supreme Court held all IEEPA tariffs unlawful (verified by grep); no invented source."}
  },
  "Q11": {
    "q11_valid_1": {
      "verdict": "yes",
      "rationale": "Item-by-item count of the submission's four discrepancies: (1) 'Proposal's location of exemptions' (proposal 91 FR 34274 vs Annex A note 34276) — NOT counted, the key expressly lists this pair as two descriptions of the same annex and therefore not a discrepancy; (2) 'Dairy scope reference' (2026-18836 clause (3), 91 FR 58320, vs the published Sept. 8 scope proclamations 58331/58339) — counted, key item 4; (3) 'Description of the 60 economies' (notice 91 FR 47318 quote verified verbatim against the document vs proposal 91 FR 34274 and the notice's own enforce-only list of six) — counted, key item 3; (4) 'Printed start date after suspension' (11046 clauses/recitals at 46640–41 vs 11056 clause (1) amendment of the Annex II chapeaux at 54790–91) — counted, key item 9. Total valid discrepancies: 3."
    },
    "q11_valid_2": {"verdict": "yes", "rationale": "Same total: 3 valid discrepancies (items 2, 3 and 4 above)."},
    "q11_valid_3": {"verdict": "yes", "rationale": "Same total: 3 valid discrepancies (items 2, 3 and 4 above)."},
    "q11_valid_4": {"verdict": "no", "rationale": "Same total: 3 valid discrepancies, short of four; the fourth listed item is the annex-description pair the key excludes."},
    "q11_valid_5": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_valid_6": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_valid_7": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_valid_8": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_valid_10": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_valid_12": {"verdict": "no", "rationale": "Same total: 3."},
    "q11_cite": {"verdict": "no", "rationale": "Each listed item cites document numbers and FR pages for both sides."},
    "q11_fab": {"verdict": "no", "rationale": "The quoted notice sentence at 91 FR 47318 was verified verbatim; no invented source or quotation."}
  },
  "Q12": {
    "q12a": {"verdict": "yes", "rationale": "Cambodia $0; Malaysia $60,000 × 10% = $6,000."},
    "q12b_exempt": {"verdict": "yes", "rationale": "Boswellia: Malaysia $0 and Taiwan $0."},
    "q12b_dutiable": {"verdict": "yes", "rationale": "Bangladesh $10,000; Argentina $10,000."},
    "q12c_taiwan": {"verdict": "yes", "rationale": "Argan oil of Taiwan: $0 (not the 6% net rate)."},
    "q12c_japan": {"verdict": "yes", "rationale": "(12.5% − 4%) × $100,000 = $8,500."},
