  },
  "Q13": {
    "q13a": {"verdict": "yes", "rationale": "($200,000 − $60,000) × 25% = $35,000, with the 15% floor checked; cites 2026-11314 clause (2)."},
    "q13b": {"verdict": "yes", "rationale": "$200,000 × 25% = $50,000."},
    "q13c": {"verdict": "yes", "rationale": "'No USMCA qualification: $200,000 × 25% = $50,000'."},
